"1262 :   private void checkPropertyAccess(JSType childType, String propName,
1263 :       NodeTraversal t, Node n) {
1264 :     ObjectType objectType = childType.dereference();
1265 :     if (objectType != null) {
1266 :       JSType propType = getJSType(n);
1267 :       if ((!objectType.hasProperty(propName) ||
1268 :            objectType.equals(typeRegistry.getNativeType(UNKNOWN_TYPE))) &&
1269 :           propType.equals(typeRegistry.getNativeType(UNKNOWN_TYPE))) {
1270 :         if (objectType instanceof EnumType) {
1271 :           report(t, n, INEXISTENT_ENUM_ELEMENT, propName);
1272 :         } else if (!objectType.isEmptyType() &&
1273 :             reportMissingProperties && !isPropertyTest(n)) {
1274 :           if (!typeRegistry.canPropertyBeDefined(objectType, propName)) {
1275 :             report(t, n, INEXISTENT_PROPERTY, propName,
1276 :                 validator.getReadableJSTypeName(n.getFirstChild(), true));
1277 :           }
1278 :         }
1279 :       }
1280 :     } else {
1281 :       // TODO(nicksantos): might want to flag the access on a non object when
1282 :       // it's impossible to get a property from this type.
1283 :     }
1284 :   }"

